const indexes: Record<AppLocale, number> = { 'en-GB': 0, 'de-DE': 1, 'es-ES': 2, 'fr-FR': 3, 'hr-HR': 4 };
export const TENANT_UI_TRANSLATIONS = Object.fromEntries((Object.keys(indexes) as AppLocale[]).map((locale) => [locale, Object.fromEntries(rows.map((row) => [row[0], row[indexes[locale]]]))])) as Record<AppLocale, TenantUiCatalog>;

export function translateTenantUi(locale: AppLocale, englishText: string): string {
  return TENANT_UI_TRANSLATIONS[locale][englishText] ?? TENANT_UI_TRANSLATIONS['en-GB'][englishText] ?? englishText;
}

const TENANT_UI_CANONICAL_BY_LOCALE = Object.fromEntries(
  (Object.keys(indexes) as AppLocale[]).map((locale) => [
    locale,
    Object.fromEntries(rows.map((row) => [row[indexes[locale]].replace(/\s+/g, ' ').trim(), row[0]]))
  ])
) as Record<AppLocale, Record<string, string>>;

export function canonicalTenantUiText(locale: AppLocale, displayedText: string): string {
  const normalized = displayedText.replace(/\s+/g, ' ').trim();
  return TENANT_UI_CANONICAL_BY_LOCALE[locale][normalized] ?? displayedText;
}
